select id, round, speaker, content,created_at
from diary_conversations
where session_id = #{sessionId}

    AND round < #{cursor}

order by round

    limit #{size}

select count(*) from diary_conversations where session_id = #{sessionId}
and round > 0
limit 1

select id, title, status, version_group, last_round, raw_facts, raw_facts_last_round, started_at, updated_at, finished_at
